window.MG_LAZY_DATA["data/lazy/resources/security-v26-017-b033796bce8774f7.json"]={sha256:"b033796bce8774f7b111db9614119e35e231dc2db39fd4091236c774b8a45a9d",value:{"sources":[{"id":"v26-case-421e40653af48b12","url":"https://www.wireguard.com/protocol/","title":"WireGuard: Protocol and Cryptography","titleEn":"WireGuard: Protocol and Cryptography","publisher":"WireGuard","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-017","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-017","related":[{"id":"security-v26-018","referenceUrls":["https://www.rfc-editor.org/rfc/rfc4033.html"],"title":"DNSSEC：信任鏈與金鑰輪替等待","titleEn":"DNSSEC: trust chains and rollover waits","why":"用兩課的可觀察驗收條件比較模型邊界：1440與1420標為上層封包的前置預算，不當作應用payload保證；路由與來源檢查皆有負例。 交付雙peer路由表、兩種封包預算與可回復設定差異。","whyEn":"Compare model boundaries using observable acceptance criteria: Label 1440 and 1420 as preliminary inner-packet budgets, not guaranteed application payload, with negative routing and source-validation cases. Deliver two-peer routing tables, both packet budgets and reversible configuration changes.","difference":"為example.test畫出DNSKEY、DS、RRSIG及RRset關係；用時間線比較驗證器快取的舊資料與新簽章可見時刻。","differenceEn":"Map DNSKEY, DS, RRSIG and RRsets for example.test; compare cached old data with new-signature visibility on a timeline.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["封包剩餘預算=路徑MTU−外層IP−UDP−WireGuard資料封裝；此預算尚未扣內層協定與可能填補。 路徑MTU1500位元組；無選項IPv4表頭20、UDP8、資料封裝32位元組。 1500−20−8−32=1440位元組；外層改無擴充IPv6表頭40時剩1420位元組。","本題單一RRset的保守等待下限=舊TTL+時鐘誤差裕度；完整輪替還需考慮父區DS與其他快取，不能只套此一算式。 教學RRset舊TTL3600秒，時鐘裕度300秒；本題不模擬父區更新。 3600+300=3900秒；舊TTL改7200秒時下限7500秒。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Remaining packet budget equals path MTU minus outer IP, UDP and WireGuard data overhead; it is before inner protocols and possible padding. Path MTU is 1500 bytes; option-free IPv4 header is 20, UDP 8 and data encapsulation 32 bytes. 1500−20−8−32=1440 bytes; using a 40-byte IPv6 header without extensions leaves 1420 bytes.","A conservative wait lower bound for one RRset is old TTL plus clock-error margin; complete rollover also considers parent DS and other caches. A teaching RRset has old TTL 3600 seconds and clock margin 300 seconds; parent-zone updates are outside this calculation. 3600+300=3900 seconds; old TTL 7200 gives a 7500-second lower bound.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-027","referenceUrls":["https://nginx.org/en/docs/http/ngx_http_realip_module.html"],"title":"NGINX 反向代理：真實來源與標頭信任界線","titleEn":"NGINX reverse proxy: source identity and header trust","why":"用兩課的可觀察驗收條件比較模型邊界：1440與1420標為上層封包的前置預算，不當作應用payload保證；路由與來源檢查皆有負例。 交付雙peer路由表、兩種封包預算與可回復設定差異。","whyEn":"Compare model boundaries using observable acceptance criteria: Label 1440 and 1420 as preliminary inner-packet budgets, not guaranteed application payload, with negative routing and source-validation cases. Deliver two-peer routing tables, both packet budgets and reversible configuration changes.","difference":"畫出客戶、邊緣代理、內部代理與應用四段；將socket peer、X-Forwarded-For與應用採用來源分欄，逐跳標示誰有權新增資料。","differenceEn":"Map client, edge proxy, internal proxy and app; separate socket peer, X-Forwarded-For and adopted source, marking which hop can append trusted data.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["封包剩餘預算=路徑MTU−外層IP−UDP−WireGuard資料封裝；此預算尚未扣內層協定與可能填補。 路徑MTU1500位元組；無選項IPv4表頭20、UDP8、資料封裝32位元組。 1500−20−8−32=1440位元組；外層改無擴充IPv6表頭40時剩1420位元組。","來源追溯覆蓋率=同時具有可信代理鏈與關聯ID的請求/全部測試請求；偽造標頭不能因語法有效就受信任。 合成200筆請求中，160筆具有完整可信鏈與關聯ID，40筆缺一項。 160/200×100=80%；補齊30筆後190/200×100=95%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Remaining packet budget equals path MTU minus outer IP, UDP and WireGuard data overhead; it is before inner protocols and possible padding. Path MTU is 1500 bytes; option-free IPv4 header is 20, UDP 8 and data encapsulation 32 bytes. 1500−20−8−32=1440 bytes; using a 40-byte IPv6 header without extensions leaves 1420 bytes.","Source-lineage coverage is requests with both trusted proxy chain and correlation ID divided by all test requests; syntactically valid headers are not inherently trusted. Of 200 synthetic requests, 160 have complete trusted lineage and correlation IDs, while 40 miss one requirement. 160/200×100=80%; repairing 30 yields 190/200×100=95%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-c808154cca2b42af","url":"https://www.rfc-editor.org/rfc/rfc4033.html","title":"RFC 4033: DNS Security Introduction and Requirements","titleEn":"RFC 4033: DNS Security Introduction and Requirements","publisher":"IETF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-ddacc1191f5f6eb4","url":"https://nginx.org/en/docs/http/ngx_http_realip_module.html","title":"NGINX real IP module","titleEn":"NGINX real IP module","publisher":"NGINX","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
